import { parseApprovalRequired, withApproval } from '@/Domain/pos/approval';
import { useTermText } from '@/lib/terms';

export const HUES = ['teal', 'sky', 'lime', 'coral', 'butter', 'plum'];

export const NAV = [
    { id: 'sell', label: 'Sell', glyph: '🛍', url: '/pos' },
