/**
 * VenQore Station Bridge - React Utility (SaaS Cloud Edition)
 * Connects your React app to VenQore Station for hardware control.
 * The station is a hardware bridge to the cloud — no local server.
 *
 * Usage:
 *   import { AMDStation, useAMDStation } from '@/Utils/AMDStation';
 *
 *   const { isConnected, print, openDrawer } = useAMDStation();
 *   await AMDStation.print(receiptData);
 *   await AMDStation.openDrawer();
 *
 *   // Register terminal ID after login:
 *   AMDStation.registerTerminal(user.terminal_id);
 */

import { useState, useEffect } from 'react';

/**
 * Check if VenQore Station is available
 */
export function isAMDStationAvailable() {
    return typeof window !== 'undefined' && window.amdAPI !== undefined;
}

/**
 * VenQore Station API wrapper (SaaS Edition)
 */
export const AMDStation = {
    /**
     * Check if running in VenQore Station
     * Returns { isAMDStation, version, deviceId, terminalId, platform }
     */
    async check() {
        if (!isAMDStationAvailable()) return { isAMDStation: false };
        try { return await window.amdAPI.check(); }
        catch (e) { return { isAMDStation: false }; }
    },

    /**
     * Register the terminal ID assigned by the cloud after login.
     * Call this once after a user logs in and you have their terminal_id.
     * @param {number} terminalId
     */
    registerTerminal(terminalId) {
        if (!isAMDStationAvailable()) return;
        window.amdAPI.registerTerminal(terminalId);
    },

    /**
     * Get station preferences (printer, terminal ID, device ID)
     */
    async getPrefs() {
        if (!isAMDStationAvailable()) return {};
        try { return await window.amdAPI.getPrefs(); }
        catch (e) { return {}; }
    },

    /**
     * Save station preferences
     */
    async savePrefs(updates) {
        if (!isAMDStationAvailable()) return { success: false };
        try { return await window.amdAPI.savePrefs(updates); }
        catch (e) { return { success: false, error: e.message }; }
    },

    /**
     * Get available printers
     */
    async getPrinters() {
        if (!isAMDStationAvailable()) return [];
        try { return await window.amdAPI.getPrinters(); }
        catch (e) { return []; }
    },

    /**
     * Set default printer
     */
    async setDefaultPrinter(printerName) {
        if (!isAMDStationAvailable()) return { success: false };
        try { return await window.amdAPI.setDefaultPrinter(printerName); }
        catch (e) { return { success: false, error: e.message }; }
    },

    /**
     * Send a raw thermal job to VenQore Station.
     * Raw ESC/POS data must never be sent to the browser's page-print dialog.
     */
    async print(data, options = {}) {
        if (isAMDStationAvailable()) {
            // Use VenQore Station for silent printing
            const printData = {
                content: this.formatReceiptData(data),
                printerName: options.printerName,
                copies: options.copies || 1,
                paperWidth: options.paperWidth || '80mm',
                autoCut: options.autoCut !== undefined ? options.autoCut : true,
            };

            try {
                const result = await window.amdAPI.print(printData);
                return result;
            } catch (e) {
                console.error('[AMDStation] Print failed:', e);
                return { success: false, error: e.message };
            }
        } else {
            return {
                success: false,
                error: 'VenQore Station is not running. Raw thermal printing requires the desktop companion.',
            };
        }
    },

    /**
     * Open cash drawer
     */
    async openDrawer(printerName) {
        if (!isAMDStationAvailable()) {
            console.warn('[AMDStation] Cash drawer not available in browser');
            return { success: false, error: 'Cash drawer requires VenQore Station' };
        }

        try {
            return await window.amdAPI.openDrawer(printerName);
        } catch (e) {
            console.error('[AMDStation] Drawer failed:', e);
            return { success: false, error: e.message };
        }
    },

    /**
     * Print and open drawer in one action
     */
    async printAndOpenDrawer(data, options = {}) {
        const printResult = await this.print(data, options);

        if (printResult?.success && options.openDrawer !== false) {
            const drawer = await this.openDrawer(options.printerName);
            if (!drawer?.success) {
                window.dispatchEvent(new CustomEvent('amd:toast', { detail: {
                    message: `Receipt printed. ${drawer?.error || 'Cash drawer request failed.'}`, type: 'warning',
                } }));
            }
            return { ...printResult, drawer };
        }

        return printResult;
    },

    /**
     * Format receipt data for electron-pos-printer
     */
    formatReceiptData(data) {
        // If already formatted, return as-is
        if (Array.isArray(data) && data[0]?.type) {
            return data;
        }

        // Convert simple object to print format
        const content = [];

        // Header
        if (data.businessName) {
            content.push({
                type: 'text',
                value: data.businessName,
                style: { fontWeight: '700', textAlign: 'center', fontSize: '24px' }
            });
        }

        if (data.businessAddress) {
            content.push({
                type: 'text',
                value: data.businessAddress,
                style: { textAlign: 'center', fontSize: '12px' }
            });
        }

        if (data.businessPhone) {
            content.push({
                type: 'text',
                value: data.businessPhone,
                style: { textAlign: 'center', fontSize: '12px' }
            });
        }

        // Divider
        content.push({
            type: 'text',
            value: '--------------------------------',
            style: { textAlign: 'center' }
        });

        // Invoice info
        if (data.invoiceNumber) {
            content.push({
                type: 'text',
                value: `Invoice: ${data.invoiceNumber}`,
                style: { fontSize: '14px' }
            });
        }

        if (data.date) {
            content.push({
                type: 'text',
                value: `Date: ${data.date}`,
                style: { fontSize: '12px' }
            });
        }

        if (data.customerName) {
            content.push({
                type: 'text',
                value: `Customer: ${data.customerName}`,
                style: { fontSize: '12px' }
            });
        }

        // Divider
        content.push({
            type: 'text',
            value: '--------------------------------',
            style: { textAlign: 'center' }
        });

        // Items
        if (data.items && Array.isArray(data.items)) {
            data.items.forEach((item, index) => {
                content.push({
                    type: 'text',
                    value: item.name,
                    style: { fontSize: '13px' }
                });
                content.push({
                    type: 'text',
                    value: `${item.qty} x ${item.price} = ${item.total}`,
                    style: { textAlign: 'right', fontSize: '12px' }
                });
            });
        }

        // Divider
        content.push({
            type: 'text',
            value: '--------------------------------',
            style: { textAlign: 'center' }
        });

        const currencySymbol = data.currencySymbol || (window.amdSettings?.currency_symbol || '') + ' ';

        // Totals
        for (const [key, label] of [['serviceCharge', 'Service charge'], ['tipAmount', 'Tip'], ['deliveryCharge', 'Delivery'], ['roundOff', 'Round off']]) {
            if (Number(String(data[key] ?? 0).replaceAll(',', '')) !== 0) {
                content.push({ type: 'text', value: `${label}: ${currencySymbol}${data[key]}`, style: { textAlign: 'right' } });
            }
        }
        if (data.subtotal !== undefined) {
            content.push({
                type: 'text',
                value: `Subtotal: ${currencySymbol}${data.subtotal}`,
                style: { textAlign: 'right' }
            });
        }

        if (data.tax !== undefined && Number(String(data.tax).replaceAll(',', '')) > 0) {
            content.push({
                type: 'text',
                value: `Tax: ${currencySymbol}${data.tax}`,
                style: { textAlign: 'right', fontSize: '12px' }
            });
        }

        if (data.discount !== undefined && Number(String(data.discount).replaceAll(',', '')) > 0) {
            content.push({
                type: 'text',
                value: `Discount: -${currencySymbol}${data.discount}`,
                style: { textAlign: 'right', fontSize: '12px' }
            });
        }

        content.push({
            type: 'text',
            value: `TOTAL: ${currencySymbol}${data.total}`,
            style: { fontWeight: '700', textAlign: 'right', fontSize: '18px' }
        });

        if (data.paidAmount !== undefined) {
            content.push({
                type: 'text',
                value: `Paid: ${currencySymbol}${data.paidAmount}`,
                style: { textAlign: 'right' }
            });
        }

        if (data.changeAmount !== undefined && Number(String(data.changeAmount).replaceAll(',', '')) > 0) {
            content.push({
                type: 'text',
                value: `Change: ${currencySymbol}${data.changeAmount}`,
                style: { textAlign: 'right' }
            });
        }

        if (data.balanceAmount !== undefined) {
            content.push({ type: 'text', value: `Balance due: ${currencySymbol}${data.balanceAmount}`, style: { textAlign: 'right' } });
        }

        // Footer
        content.push({
            type: 'text',
            value: '--------------------------------',
            style: { textAlign: 'center' }
        });

        content.push({
            type: 'text',
            value: 'Thank You!',
            style: { fontWeight: '700', textAlign: 'center', fontSize: '16px' }
        });

        if (data.footerMessage) {
            content.push({
                type: 'text',
                value: data.footerMessage,
                style: { textAlign: 'center', fontSize: '11px' }
            });
        }

        // Barcode (If using electron-pos-printer supported format)
        if (data.showBarcode && data.invoiceNumber) {
            content.push({
                type: 'barCode',
                value: data.invoiceNumber.toString(),
                height: 40,
                width: 2,
                displayValue: true,
                fontsize: 8
            });
        }

        return content;
    }
};

/**
 * React Hook for VenQore Station
 */
export function useAMDStation() {
    const [isConnected, setIsConnected] = useState(false);
    const [printers, setPrinters] = useState([]);
    const [defaultPrinter, setDefaultPrinter] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        async function init() {
            const status = await AMDStation.check();
            setIsConnected(status.isAMDStation);

            if (status.isAMDStation) {
                const printerList = await AMDStation.getPrinters();
                setPrinters(printerList);

                // Preserve the saved choice even when that device is disconnected.
                // Never silently replace it with a system PDF printer.
                const prefs = await AMDStation.getPrefs();
                setDefaultPrinter(prefs.defaultPrinter || null);
            }

            setLoading(false);
        }

        init();

        // Listen for VenQore Station ready event
        const handleReady = (e) => {
            console.log('[AMDStation Hook] Station ready:', e.detail);
            init();
        };
        window.addEventListener('amd-station-ready', handleReady);

        return () => {
            window.removeEventListener('amd-station-ready', handleReady);
        };
    }, []);

    return {
        isConnected,
        loading,
        printers,
        defaultPrinter,
        setDefaultPrinter: async (name) => {
            const result = await AMDStation.setDefaultPrinter(name);
            if (result?.success) setDefaultPrinter(name);
            return result;
        },
        print: (data, options) => AMDStation.print(data, { ...options, printerName: options?.printerName || defaultPrinter }),
        openDrawer: () => AMDStation.openDrawer(defaultPrinter),
        printAndOpenDrawer: (data, options) => AMDStation.printAndOpenDrawer(data, { ...options, printerName: options?.printerName || defaultPrinter }),
    };
}

export default AMDStation;

/**
 * React Hook: Barcode Scanner via COM Port
 *
 * Usage:
 *   const { lastBarcode, isConnected, connect } = useBarcodeScannerPort('COM3', 9600);
 */
export function useBarcodeScannerPort(portPath = null, baudRate = 9600) {
    const [lastBarcode, setLastBarcode] = useState(null);
    const [isConnected, setIsConnected] = useState(false);
    const [error, setError] = useState(null);

    const connect = async (port, baud) => {
        if (!isAMDStationAvailable()) return;
        try {
            const result = await window.amdAPI.openScanner(port || portPath, baud || baudRate);
            setIsConnected(result.success);
            if (!result.success) setError(result.error);
        } catch (e) {
            setError(e.message);
        }
    };

    const disconnect = async () => {
        if (!isAMDStationAvailable()) return;
        await window.amdAPI.closeSerial('scanner');
        setIsConnected(false);
    };

    useEffect(() => {
        if (!isAMDStationAvailable()) return;

        // Auto-connect if portPath provided
        if (portPath) connect(portPath, baudRate);

        // Also listen for keyboard-wedge barcodes from shell
        const handleBarcode = (e) => {
            if (e.detail) setLastBarcode(e.detail);
        };
        window.addEventListener('amd:barcode-scan', handleBarcode);

        // Listen from preload bridge
        const cleanup = window.amdAPI.onBarcodeScan?.((barcode) => {
            setLastBarcode(barcode);
        });

        return () => {
            window.removeEventListener('amd:barcode-scan', handleBarcode);
            if (typeof cleanup === 'function') cleanup();
        };
    }, [portPath]);

    return { lastBarcode, isConnected, error, connect, disconnect };
}

/**
 * React Hook: Weight Scale via COM Port
 *
 * Usage:
 *   const { weight, isConnected, connect } = useWeightScale('COM4', 9600);
 */
export function useWeightScale(portPath = null, baudRate = 9600) {
    const [weight, setWeight] = useState(null);
    const [rawReading, setRawReading] = useState(null);
    const [isConnected, setIsConnected] = useState(false);
    const [error, setError] = useState(null);

    const connect = async (port, baud) => {
        if (!isAMDStationAvailable()) return;
        try {
            const result = await window.amdAPI.openScale(port || portPath, baud || baudRate);
            setIsConnected(result.success);
            if (!result.success) setError(result.error);
        } catch (e) {
            setError(e.message);
        }
    };

    const disconnect = async () => {
        if (!isAMDStationAvailable()) return;
        await window.amdAPI.closeSerial('scale');
        setIsConnected(false);
        setWeight(null);
    };

    useEffect(() => {
        if (!isAMDStationAvailable()) return;

        if (portPath) connect(portPath, baudRate);

        const cleanup = window.amdAPI.onScaleReading?.((data) => {
            setWeight(data.weight);
            setRawReading(data.raw);
        });

        return () => {
            if (typeof cleanup === 'function') cleanup();
        };
    }, [portPath]);

    return { weight, rawReading, isConnected, error, connect, disconnect };
}

/**
 * React Hook: Auto-Updater
 *
 * Usage:
 *   const { updateAvailable, updateVersion, progress, isReady, downloadUpdate, installUpdate } = useAutoUpdater();
 */
export function useAutoUpdater() {
    const [updateAvailable, setUpdateAvailable] = useState(false);
    const [updateVersion, setUpdateVersion] = useState(null);
    const [progress, setProgress] = useState(0);
    const [isDownloading, setIsDownloading] = useState(false);
    const [isReady, setIsReady] = useState(false);

    useEffect(() => {
        if (!isAMDStationAvailable()) return;

        const cleanupAvailable = window.amdAPI.onUpdateAvailable?.((info) => {
            setUpdateAvailable(true);
            setUpdateVersion(info.version);
            setIsDownloading(true);
        });

        const cleanupProgress = window.amdAPI.onUpdateProgress?.((data) => {
            setProgress(data.percent);
        });

        const cleanupReady = window.amdAPI.onUpdateReady?.((info) => {
            setIsReady(true);
            setIsDownloading(false);
            setProgress(100);
        });

        return () => {
            if (typeof cleanupAvailable === 'function') cleanupAvailable();
            if (typeof cleanupProgress === 'function') cleanupProgress();
            if (typeof cleanupReady === 'function') cleanupReady();
        };
    }, []);

    return {
        updateAvailable,
        updateVersion,
        progress,
        isDownloading,
        isReady,
        downloadUpdate: () => window.amdAPI?.downloadUpdate?.(),
        installUpdate: () => window.amdAPI?.installUpdate?.(),
    };
}

import { escapePrintData, printBrowserHtml } from './BrowserPrint';
/**
 * ZReportPrintService.js
 *
 * Formats and prints Register End-of-Shift Z-Reports on 80mm/58mm thermal printers.
 * Supports ESC/POS via AMDStation and clean browser thermal printing.
 */

import { AMDStation, isAMDStationAvailable } from './AMDStation';
import { formatCurrency } from './format';

export const ZReportPrintService = {
    /**
     * Print Z-Report
     * @param {Object} zReport - Z-report data from RegisterShiftController
     * @param {Object} options - { paperWidth: '80mm'|'58mm' }
     */
    async printZReport(zReport, options = {}) {
        if (!zReport) {
            console.warn('[ZReportPrintService] No Z-report data provided');
            return { success: false, error: 'Empty Z-report data' };
        }

        const paperWidth = options.paperWidth || '80mm';

        try {
            if (isAMDStationAvailable()) {
                const escPosContent = this.formatEscPos(zReport, { paperWidth });
                const result = await AMDStation.print(escPosContent, {
                    paperWidth,
                    copies: 1,
                    printerName: options.printerName,
                });

                if (result?.success === true) {
                    return { success: true, method: 'station' };
                }

                throw new Error(result?.error || 'VenQore Station could not print the Z-report to the selected printer.');
            }

            // Fallback to iframe HTML print
            await this.printViaIframe(zReport, { paperWidth });
            return { success: true, method: 'browser' };
        } catch (err) {
            console.error('[ZReportPrintService] Print error:', err);
            if (typeof window !== 'undefined') {
                window.dispatchEvent(new CustomEvent('amd:toast', {
                    detail: { message: `${err.message || 'Thermal printing failed'} Check the Station printer selection and connection, then retry.`, type: 'error' },
                }));
            }
            return { success: false, error: err.message || 'Failed to print Z-Report' };
        }
    },

    /**
     * Format for ESC/POS Thermal Printers
     */
    formatEscPos(zReport, options = {}) {
        const ESC = '\x1B';
        const GS  = '\x1D';
        const LF  = '\n';

        const store = zReport.store || {};
        const shift = zReport.shift || {};
        const sales = zReport.sales || {};
        const recon = zReport.cash_reconciliation || {};
        const tenders = zReport.tenders || {};

        let text = '';
        // Initialize
        text += ESC + '@';
        // Center alignment
        text += ESC + 'a' + '\x01';
        // Double height & bold for title
        text += ESC + '!' + '\x18';
        text += (store.name || 'VENQORE POS').toUpperCase() + LF;
        text += ESC + '!' + '\x00'; // Normal
        if (store.address) text += store.address + LF;
        if (store.phone) text += 'Tel: ' + store.phone + LF;
        if (store.tax_number) text += 'TRN: ' + store.tax_number + LF;

        text += '================================' + LF;
        text += ESC + '!' + '\x08'; // Bold
        text += '*** REGISTER Z-REPORT ***' + LF;
        text += ESC + '!' + '\x00';
        text += '================================' + LF;

        // Left align
        text += ESC + 'a' + '\x00';
        text += `Shift ID   : #${shift.id}\n`;
        text += `Register   : ${shift.register_id || 'REG-1'}\n`;
        text += `Cashier    : ${shift.opened_by || 'Staff'}\n`;
        text += `Closed By  : ${shift.closed_by || 'Manager'}\n`;
        text += `Opened At  : ${shift.opened_at || '-'}\n`;
        text += `Closed At  : ${shift.closed_at || '-'}\n`;
        text += '--------------------------------\n';

        text += ESC + '!' + '\x08';
        text += 'SALES SUMMARY\n';
        text += ESC + '!' + '\x00';
        text += `Total Bills      : ${sales.count || 0}\n`;
        text += `Gross Sales      : ${formatCurrency(sales.gross_sales || 0)}\n`;
        text += `Discounts        : ${formatCurrency(sales.discounts || 0)}\n`;
        text += `Net Sales        : ${formatCurrency(sales.net_sales || 0)}\n`;
        text += `Tax Collected    : ${formatCurrency(sales.tax || 0)}\n`;
        if (sales.tips > 0) text += `Tips Collected   : ${formatCurrency(sales.tips)}\n`;
        if (sales.service_charges > 0) text += `Service Charge   : ${formatCurrency(sales.service_charges)}\n`;
        text += '--------------------------------\n';
        text += ESC + '!' + '\x08';
        text += `TOTAL REVENUE    : ${formatCurrency(sales.grand_total || 0)}\n`;
        text += ESC + '!' + '\x00';
        text += '--------------------------------\n';

        text += ESC + '!' + '\x08';
        text += 'PAYMENT BREAKDOWN\n';
        text += ESC + '!' + '\x00';
        text += `Cash             : ${formatCurrency(tenders.cash || 0)}\n`;
        text += `Card / Digital   : ${formatCurrency(tenders.card || 0)}\n`;
        text += `Credit (A/R)     : ${formatCurrency(tenders.credit || 0)}\n`;
        if (tenders.other > 0) text += `Other            : ${formatCurrency(tenders.other)}\n`;
        text += '--------------------------------\n';

        text += ESC + '!' + '\x08';
        text += 'CASH DRAWER RECONCILIATION\n';
        text += ESC + '!' + '\x00';
        text += `Opening Float    : ${formatCurrency(recon.opening_float || 0)}\n`;
        text += `+ Cash Sales     : ${formatCurrency(recon.cash_sales || 0)}\n`;
        text += `+ Cash In        : ${formatCurrency(recon.cash_in || 0)}\n`;
        text += `- Cash Out       : ${formatCurrency(recon.cash_out || 0)}\n`;
        text += `--------------------------------\n`;
        text += `Expected Cash    : ${formatCurrency(recon.expected_cash || 0)}\n`;
        text += `Actual Counted   : ${formatCurrency(recon.counted_cash || 0)}\n`;
        text += `--------------------------------\n`;
        text += ESC + '!' + '\x08';
        const varPrefix = recon.variance > 0 ? '+' : '';
        text += `VARIANCE (${recon.variance_type?.toUpperCase()}) : ${varPrefix}${formatCurrency(recon.variance || 0)}\n`;
        text += ESC + '!' + '\x00';
        text += '================================\n';
        for (const movement of zReport.movements || []) {
            text += `[${String(movement.type || '').toUpperCase()}] ${movement.reason || ''}: ${formatCurrency(movement.amount || 0)}\n`;
        }
        if (shift.notes) text += `Notes: ${shift.notes}\n`;
        text += `Printed: ${zReport.printed_at || new Date().toLocaleString()}\n`;
        text += '\n\n\n';
        text += GS + 'V' + '\x41' + '\x03'; // Cut paper

        // electron-pos-printer accepts structured rows, not raw ESC/POS bytes.
        return text.replace(/\x1b[@]/g, '').replace(/\x1b[a!][\s\S]/g, '').replace(/\x1dV[\s\S]{2}/g, '')
            .trim().split('\n').map(value => ({
                type: 'text', value,
                style: { fontFamily: 'monospace', fontSize: '11px', whiteSpace: 'pre-wrap' },
            }));
    },

    /**
     * Print via Browser Iframe
     */
    printViaIframe(zReport, options = {}) {
        zReport = escapePrintData(zReport);
            const width = options.paperWidth === '58mm' ? '54mm' : '76mm';
            const store = zReport.store || {};
            const shift = zReport.shift || {};
            const sales = zReport.sales || {};
            const recon = zReport.cash_reconciliation || {};
            const tenders = zReport.tenders || {};
            const movements = zReport.movements || [];

            const html = `
<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>Z-Report #${shift.id}</title>
    <style>
        @page {
            size: ${width} auto;
            margin: 0;
        }
        body {
            font-family: 'Courier New', Courier, monospace;
            font-size: 11px;
            width: ${width};
            margin: 0 auto;
            padding: 8px 4px;
            color: #000;
            background: #fff;
            line-height: 1.35;
        }
        .text-center { text-align: center; }
        .text-right { text-align: right; }
        .bold { font-weight: bold; }
        .title { font-size: 14px; font-weight: bold; margin-bottom: 2px; }
        .subtitle { font-size: 10px; margin-bottom: 4px; }
        .divider { border-top: 1px dashed #000; margin: 6px 0; }
        .double-divider { border-top: 2px solid #000; margin: 6px 0; }
        .row { display: flex; justify-content: space-between; margin-bottom: 2px; }
        .section-header { font-weight: bold; text-transform: uppercase; margin: 6px 0 3px 0; font-size: 11px; }
        .highlight { background: #eee; padding: 2px 0; font-weight: bold; }
        .variance-balanced { color: #000; font-weight: bold; }
        .variance-shortage { color: #000; font-weight: bold; text-decoration: underline; }
        .variance-overage { color: #000; font-weight: bold; }
    </style>
</head>
<body>
    <div class="text-center">
        <div class="title">${store.name || 'VENQORE POS'}</div>
        ${store.address ? `<div class="subtitle">${store.address}</div>` : ''}
        ${store.phone ? `<div class="subtitle">Tel: ${store.phone}</div>` : ''}
        ${store.tax_number ? `<div class="subtitle">TRN: ${store.tax_number}</div>` : ''}
    </div>

    <div class="double-divider"></div>
    <div class="text-center bold" style="font-size: 13px; letter-spacing: 1px;">
        *** REGISTER Z-REPORT ***
    </div>
    <div class="double-divider"></div>

    <div class="row"><span>Shift ID:</span><span class="bold">#${shift.id}</span></div>
    <div class="row"><span>Register:</span><span>${shift.register_id || 'REG-1'}</span></div>
    <div class="row"><span>Opened By:</span><span>${shift.opened_by || 'Staff'}</span></div>
    <div class="row"><span>Closed By:</span><span>${shift.closed_by || 'Manager'}</span></div>
    <div class="row"><span>Opened At:</span><span>${shift.opened_at || '-'}</span></div>
    <div class="row"><span>Closed At:</span><span>${shift.closed_at || '-'}</span></div>

    <div class="divider"></div>
    <div class="section-header">Sales Summary</div>
    <div class="row"><span>Total Bills:</span><span>${sales.count || 0}</span></div>
    <div class="row"><span>Gross Sales:</span><span>${formatCurrency(sales.gross_sales || 0)}</span></div>
    <div class="row"><span>Discounts:</span><span>-${formatCurrency(sales.discounts || 0)}</span></div>
    <div class="row"><span>Net Sales:</span><span>${formatCurrency(sales.net_sales || 0)}</span></div>
    <div class="row"><span>Tax Collected:</span><span>${formatCurrency(sales.tax || 0)}</span></div>
    ${sales.tips > 0 ? `<div class="row"><span>Tips:</span><span>${formatCurrency(sales.tips)}</span></div>` : ''}
    ${sales.service_charges > 0 ? `<div class="row"><span>Service Charges:</span><span>${formatCurrency(sales.service_charges)}</span></div>` : ''}
    <div class="divider"></div>
    <div class="row highlight">
        <span>TOTAL REVENUE:</span>
        <span>${formatCurrency(sales.grand_total || 0)}</span>
    </div>

    <div class="divider"></div>
    <div class="section-header">Tenders / Payment Breakdown</div>
    <div class="row"><span>Cash:</span><span>${formatCurrency(tenders.cash || 0)}</span></div>
    <div class="row"><span>Card / Digital:</span><span>${formatCurrency(tenders.card || 0)}</span></div>
    <div class="row"><span>Credit (A/R):</span><span>${formatCurrency(tenders.credit || 0)}</span></div>
    ${tenders.other > 0 ? `<div class="row"><span>Other:</span><span>${formatCurrency(tenders.other)}</span></div>` : ''}

    <div class="divider"></div>
    <div class="section-header">Cash Drawer Reconciliation</div>
    <div class="row"><span>Opening Float:</span><span>${formatCurrency(recon.opening_float || 0)}</span></div>
    <div class="row"><span>+ Cash Sales:</span><span>${formatCurrency(recon.cash_sales || 0)}</span></div>
    <div class="row"><span>+ Pay-Ins (Cash In):</span><span>${formatCurrency(recon.cash_in || 0)}</span></div>
    <div class="row"><span>- Pay-Outs (Cash Out):</span><span>-${formatCurrency(recon.cash_out || 0)}</span></div>
    <div class="divider"></div>
    <div class="row"><span>Expected in Drawer:</span><span class="bold">${formatCurrency(recon.expected_cash || 0)}</span></div>
    <div class="row"><span>Actual Counted:</span><span class="bold">${formatCurrency(recon.counted_cash || 0)}</span></div>
    <div class="divider"></div>
    <div class="row highlight ${recon.variance < 0 ? 'variance-shortage' : recon.variance > 0 ? 'variance-overage' : 'variance-balanced'}">
        <span>VARIANCE (${recon.variance_type?.toUpperCase()}):</span>
        <span>${recon.variance > 0 ? '+' : ''}${formatCurrency(recon.variance || 0)}</span>
    </div>

    ${movements.length > 0 ? `
    <div class="divider"></div>
    <div class="section-header">Cash Movements Log</div>
    ${movements.map(m => `
        <div class="row" style="font-size: 10px;">
            <span>[${m.type.toUpperCase()}] ${m.reason}</span>
            <span>${m.type === 'in' ? '+' : '-'}${formatCurrency(m.amount)}</span>
        </div>
    `).join('')}
    ` : ''}

    ${shift.notes ? `
    <div class="divider"></div>
    <div class="section-header">Shift Notes</div>
    <div style="font-size: 10px; font-style: italic;">${shift.notes}</div>
    ` : ''}

    <div class="double-divider"></div>
    <div class="text-center" style="font-size: 9px; margin-top: 6px;">
        <div>Printed at ${zReport.printed_at || new Date().toLocaleString()}</div>
        <div>End of Shift Report</div>
    </div>
</body>
</html>
            `;

        return printBrowserHtml(html, options.paperWidth);
    }
};
